目标里的 ``report.pdf`` 会被认成同一个条目：该更新的走 UPDATE，内容一致的
走 KEEP，绝不会被拆成"新建一个 + 删掉另一个"而把文件弄丢。
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Dict, List, Optional, Tuple

from . import fsops

CREATE = "create"
UPDATE = "update"
DELETE = "delete"
KEEP = "keep"


